mapper.select:
select cm.id, cm.club_id, cm.member_id, cm.role, cm.status, cm.join_time, cm.del_flag, m.nickname as nickname, m.avatar as avatar, coalesce(pg.level, 1) as level_id from club_member cm join club c on c.id = cm.club_id and c.del_flag = 0 left join ums_member m on m.id = cm.member_id left join player_growth pg on pg.member_id = cm.member_id
cm.del_flag = 0 and cm.club_id = #{clubId} and cm.member_id = #{memberId} and cm.status = #{status}
order by cm.join_time desc

mapper.update:
update club_member
role = #{role}, status = #{status},
where id = #{id}
